begin;
create extension if not exists pgtap with schema extensions;
set local search_path = public, extensions;
select no_plan();
-- Metadata-only RLS probes; no files exist in this transactional fixture.
-- Storage's statement guard requires this for SQL DELETE probes; the real
-- removal flow is covered through Storage API in the shared Repo contract.
-- https://github.com/supabase/storage/blob/master/migrations/tenant/0055-prevent-direct-deletes.sql
set local storage.allow_delete_query = 'true';
insert into auth.users(id,email) values ('81000000-0000-4000-8000-000000000001','alice@example.test'),('81000000-0000-4000-8000-000000000002','bob@example.test'),('81000000-0000-4000-8000-000000000003',null);
