insert into public.crew_members(crew_id,user_id,role) values ('81000000-0000-4000-8000-000000000004','81000000-0000-4000-8000-000000000001','owner'),('81000000-0000-4000-8000-000000000004','81000000-0000-4000-8000-000000000002','member');
insert into public.sessions(id,kind,started_at,tz,user_id,local_date,client_updated_at) values ('81000000-0000-4000-8000-000000000007','gym',now(),'Europe/Amsterdam','81000000-0000-4000-8000-000000000001','2026-11-05',now());
