insert into public.cardio_entries(id,session_id,distance_m,duration_s,logged_at,user_id,local_date,client_updated_at) values ('81000000-0000-4000-8000-000000000011','81000000-0000-4000-8000-000000000007',5000,1800,now(),'81000000-0000-4000-8000-000000000001','2026-11-05',now());
insert into public.sessions(id,kind,started_at,tz,user_id,local_date,client_updated_at) values ('81000000-0000-4000-8000-000000000008','gym',now(),'Europe/Amsterdam','81000000-0000-4000-8000-000000000002','2026-11-05',now());
insert into public.sets(id,session_id,exercise_id,set_index,reps,weight_kg,logged_at,user_id,local_date,client_updated_at) values ('81000000-0000-4000-8000-000000000010','81000000-0000-4000-8000-000000000008','00000000-0000-4000-8000-000000000001',1,5,60,now(),'81000000-0000-4000-8000-000000000002','2026-11-05',now());
insert into public.cardio_entries(id,session_id,distance_m,duration_s,logged_at,user_id,local_date,client_updated_at) values ('81000000-0000-4000-8000-000000000012','81000000-0000-4000-8000-000000000008',5000,1800,now(),'81000000-0000-4000-8000-000000000002','2026-11-05',now());
insert into public.proof_cards(id,crew_id,day,kind,together,created_by,client_updated_at) values ('81000000-0000-4000-8000-000000000005','81000000-0000-4000-8000-000000000004','2026-11-05','lift',true,'81000000-0000-4000-8000-000000000001',now());
insert into public.proof_cards(id,crew_id,day,kind,together,created_by,client_updated_at) values ('81000000-0000-4000-8000-000000000006','81000000-0000-4000-8000-000000000004','2026-11-05','run',true,'81000000-0000-4000-8000-000000000001',now());
insert into public.proof_photos(id,card_id,user_id,storage_path,width,height,bytes,client_updated_at) values ('81000000-0000-4000-8000-000000000013','81000000-0000-4000-8000-000000000006','81000000-0000-4000-8000-000000000001','81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/81000000-0000-4000-8000-000000000001.jpg',800,1200,300000,now());
insert into public.proof_photos(id,card_id,user_id,storage_path,width,height,bytes,client_updated_at) values ('81000000-0000-4000-8000-000000000014','81000000-0000-4000-8000-000000000006','81000000-0000-4000-8000-000000000002','81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/81000000-0000-4000-8000-000000000002.jpg',800,1200,300000,now());
insert into storage.objects(bucket_id,name) values ('proof','81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/81000000-0000-4000-8000-000000000001.jpg');
select is((select file_size_limit from storage.buckets where id='proof'),5000000::bigint,'server bucket enforces decimal 5 MB');
select is((select allowed_mime_types from storage.buckets where id='proof'),array['image/jpeg','image/webp'],'server bucket accepts only JPEG and WebP');
select is((select public from storage.buckets where id='proof'),false,'bucket is private');
select ok(not has_table_privilege('anon','public.proof_cards','SELECT'),'anonymous cannot read cards');
select ok(not has_function_privilege('anon','public.proof_entry_owned(uuid,text,uuid)','EXECUTE'),'helper is not anonymous');
select throws_ok('insert into public.proof_photos(id,card_id,user_id,storage_path,width,height,bytes,client_updated_at) values (''81000000-0000-4000-8000-000000000022'',''81000000-0000-4000-8000-000000000006'',''81000000-0000-4000-8000-000000000001'',''81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/duplicate.jpg'',800,1200,300000,now())','23505',null,'one photo per user per card even with a different path');
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',true);
select lives_ok('insert into public.proof_links(id,card_id,entry_table,entry_id,user_id,client_updated_at) values (''81000000-0000-4000-8000-000000000030'',''81000000-0000-4000-8000-000000000005'',''sets'',''81000000-0000-4000-8000-000000000009'',''81000000-0000-4000-8000-000000000001'',now())','owner can link own set');
select lives_ok('insert into public.proof_links(id,card_id,entry_table,entry_id,user_id,client_updated_at) values (''81000000-0000-4000-8000-000000000031'',''81000000-0000-4000-8000-000000000006'',''cardio_entries'',''81000000-0000-4000-8000-000000000011'',''81000000-0000-4000-8000-000000000001'',now())','owner can link own run');
select throws_ok('insert into public.proof_links(id,card_id,entry_table,entry_id,user_id,client_updated_at) values (''81000000-0000-4000-8000-000000000032'',''81000000-0000-4000-8000-000000000005'',''sets'',''81000000-0000-4000-8000-000000000010'',''81000000-0000-4000-8000-000000000001'',now())','42501',null,'cannot claim a partner set with my user_id');
select throws_ok('insert into public.proof_links(id,card_id,entry_table,entry_id,user_id,client_updated_at) values (''81000000-0000-4000-8000-000000000033'',''81000000-0000-4000-8000-000000000006'',''cardio_entries'',''81000000-0000-4000-8000-000000000012'',''81000000-0000-4000-8000-000000000001'',now())','42501',null,'cannot claim a partner run with my user_id');
select throws_ok('insert into public.proof_links(id,card_id,entry_table,entry_id,user_id,client_updated_at) values (''81000000-0000-4000-8000-000000000034'',''81000000-0000-4000-8000-000000000006'',''cardio_entries'',''81000000-0000-4000-8000-000000000012'',''81000000-0000-4000-8000-000000000002'',now())','42501',null,'cannot insert a link on behalf of partner');
select throws_ok('insert into public.proof_links(id,card_id,entry_table,entry_id,user_id,client_updated_at) values (''81000000-0000-4000-8000-000000000035'',''81000000-0000-4000-8000-000000000006'',''sets'',''81000000-0000-4000-8000-000000000009'',''81000000-0000-4000-8000-000000000001'',now())','42501',null,'entry kind must match card kind');
select throws_ok('update public.proof_cards set created_by=''81000000-0000-4000-8000-000000000002'' where id=''81000000-0000-4000-8000-000000000006''','42501',null,'creator is immutable');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000002',true);
select is((select count(*) from public.proof_cards),2::bigint,'partner reads crew cards');
select is((select count(*) from public.proof_photos),2::bigint,'partner reads photos');
select is((select count(*) from storage.objects where bucket_id='proof'),1::bigint,'partner reads storage objects');
select lives_ok('insert into public.proof_links(id,card_id,entry_table,entry_id,user_id,client_updated_at) values (''81000000-0000-4000-8000-000000000036'',''81000000-0000-4000-8000-000000000006'',''cardio_entries'',''81000000-0000-4000-8000-000000000012'',''81000000-0000-4000-8000-000000000002'',now())','partner adds their own run link');
delete from public.proof_photos where id='81000000-0000-4000-8000-000000000013';
select is((select count(*) from public.proof_photos where id='81000000-0000-4000-8000-000000000013'),1::bigint,'partner cannot delete owner photo');
delete from storage.objects where bucket_id='proof' and name='81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/81000000-0000-4000-8000-000000000001.jpg';
select is((select count(*) from storage.objects where bucket_id='proof'),1::bigint,'partner cannot delete owner storage object');
select throws_ok('insert into storage.objects(bucket_id,name) values (''proof'',''81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/81000000-0000-4000-8000-000000000001.jpg'')','42501',null,'partner cannot upload over owner path');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.proof_cards),0::bigint,'stranger cannot read proof_cards');
select is((select count(*) from public.proof_links),0::bigint,'stranger cannot read proof_links');
select is((select count(*) from public.proof_photos),0::bigint,'stranger cannot read proof_photos');
select is((select count(*) from storage.objects where bucket_id='proof'),0::bigint,'stranger cannot read bucket objects');
select throws_ok('insert into storage.objects(bucket_id,name) values (''proof'',''81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/81000000-0000-4000-8000-000000000003.jpg'')','42501',null,'stranger cannot upload into another crew path even using own filename');
select throws_ok('insert into storage.objects(bucket_id,name) values (''proof'',''81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/81000000-0000-4000-8000-000000000001.jpg'')','42501',null,'stranger cannot upload into owner path');
select throws_ok('insert into storage.objects(bucket_id,name) values (''proof'',''invalid/path/value.jpg'')','42501',null,'malformed path is denied without UUID cast errors');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','81000000-0000-4000-8000-000000000001',true);
delete from storage.objects where bucket_id='proof' and name='81000000-0000-4000-8000-000000000004/81000000-0000-4000-8000-000000000006/81000000-0000-4000-8000-000000000001.jpg';
select is((select count(*) from storage.objects where bucket_id='proof'),0::bigint,'owner may delete own object');
reset role;
select * from finish();
rollback;
